namespace ghidra.feature.vt.gui.util;

using docking.widgets.table;
using docking.widgets.table;
using docking.widgets.table.threaded;
using ghidra.feature.vt.gui.filters;
using ghidra.feature.vt.gui.plugin;

public class AllTextFilter<T> : AbstractTextFilter<T> {

	private ThreadedTableModel<T,object> model;

	public AllTextFilter(VTController controller, GTable table, ThreadedTableModel<T,object> model) : base(controller, table, "Filter")
    {
		this.model = model;
	}

	/* @Override */
	protected Filter<T> createEmptyCopy() {
		return new(controller, table, model);
	}

	/* @Override */
	public bool passesFilter(T t) {
		string filterText = getTextFieldText();
		if (filterText == null || filterText.trim().length() == 0) {
			return true; // no text for this filter
		}

		filterText = filterText.toLowerCase();
		int columnCount = table.getColumnCount();
		for (int column = 0; column < columnCount; column++) {
			int modelColumn = table.convertColumnIndexToModel(column);
			object value = model.getColumnValueForRow(t, modelColumn);
			if (value == null) {
				continue;
			}

			if (value is DisplayStringProvider) {
				DisplayStringProvider displayable = (DisplayStringProvider) value;
				string displayString = displayable.getDisplayString();
				if (displayString != null) {
					displayString = displayString.toLowerCase();
					if (displayString.indexOf(filterText) != -1) {
						return true;
					}
				}
			}

			if (isJavaDisplayableAsString(value)) {
				string displayString = value.toString().toLowerCase();
				if (displayString.indexOf(filterText) != -1) {
					return true;
				}
			}
		}
		return false;
	}

	private bool isJavaDisplayableAsString(object value) {
		return (value is string) || (value is Number) ||
			(value is Character);
	}
}
